/**
 * Writes lib/developers/content.generated.ts: every page of the Storelib
 * Developer Hub (content/developers/*.md) and every example section
 * (content/developers/examples/*.storelib), as importable maps.
 *
 * The markdown is the source of truth and the thing a person edits. It is
 * bundled rather than read at runtime because pages under the marketing
 * layout render per request, and a file Next never traced into the
 * serverless bundle is not there to read. tests/developer-hub.test.ts fails
 * when the generated file is not what this would write.
 *
 *   npx tsx scripts/emit-developer-docs.ts
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const ROOT = join(process.cwd(), "content/developers")

function filesIn(dir: string, ext: string): Record<string, string> {
  const out: Record<string, string> = {}
  let names: string[] = []
  try { names = readdirSync(dir) } catch { return out }
  for (const name of names.filter((n) => n.endsWith(ext)).sort()) {
    out[name.slice(0, -ext.length)] = readFileSync(join(dir, name), "utf8")
  }
  return out
}

/** `index` is the hub's front page, whose slug is "". */
export function developerDocs(): Record<string, string> {
  const pages = filesIn(ROOT, ".md")
  const out: Record<string, string> = {}
  for (const [name, text] of Object.entries(pages)) out[name === "index" ? "" : name] = text
  return out
}

export function developerExamples(): Record<string, string> {
  return filesIn(join(ROOT, "examples"), ".storelib")
}

export function developerDocsModule(): string {
  const map = (o: Record<string, string>) =>
    Object.entries(o).map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`).join("\n")
  return [
    "// Generated by scripts/emit-developer-docs.ts from content/developers.",
    "// Do not edit: edit the markdown or the example and run `npx tsx scripts/emit-developer-docs.ts`.",
    "",
    "/** Each page's markdown, by slug. The front page is \"\". */",
    "export const DEVELOPER_DOCS: Record<string, string> = {",
    map(developerDocs()),
    "}",
    "",
    "/** Each example section's source, by type. */",
    "export const DEVELOPER_EXAMPLES: Record<string, string> = {",
    map(developerExamples()),
    "}",
    "",
  ].join("\n")
}

if (process.argv[1] && process.argv[1].endsWith("emit-developer-docs.ts")) {
  const out = join(process.cwd(), "lib/developers/content.generated.ts")
  writeFileSync(out, developerDocsModule())
  console.log(`wrote ${out}`)
}
